// A reply longer than the channel allows (Instagram: 1000 characters) would be rejected by the
// channel after Chatwoot accepted it - a silent failure. Split on paragraph, then sentence, then word.
const LIMITS = {"instagram":1000,"messenger":2000,"tiktok":1000,"sms":1600,"telegram":4096,"whatsapp":4096,"line":5000};
const limit = LIMITS[$('Reply In').first().json.source] || 4096;
let rest = String($input.first().json.output || '').trim();
const parts = [];
while (rest.length > limit) {
  const win = rest.slice(0, limit);
  let cut = win.lastIndexOf('\n\n');
  if (cut < limit * 0.5) cut = Math.max(win.lastIndexOf('. '), win.lastIndexOf('! '), win.lastIndexOf('? '), win.lastIndexOf('\n')) + 1;
  if (cut < limit * 0.5) cut = win.lastIndexOf(' ');
  if (cut <= 0) cut = limit;
  parts.push(rest.slice(0, cut).trim());
  rest = rest.slice(cut).trim();
}
if (rest || !parts.length) parts.push(rest);
return parts.map((chunk, index) => ({ json: { chunk, index, parts: parts.length } }));

